   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="珂芙尼尔：玩家名字，那个商人临时改变时间，想要约吾出去见一面。\n珂芙尼尔：看汝睡得正香，吾就没有打搅汝。\n珂芙尼尔：汝的房门是露可打开的，吾可不会这么没有礼貌。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1504.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 913.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
