   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="接下来是一张照片，很明显是珂芙尼尔用终端的前置摄像头拍的，你闭着眼平静地睡着，珂芙尼尔一手比耶，半蹲在你床边，露可在你们中间仰头看着镜头。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1504.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
